namespace ActivityGearSync.Shared;

public static class IconGenerator
{
    // Pre-generated 256x256 PNG icon: Orange gear cog on gradient background
    // Represents "gear" (equipment) and settings/editing functionality
    private const string IconBase64 = "";

    public static void EnsureIconExists(string outputPath)
    {
        if (File.Exists(outputPath))
        {
            return;
        }

        string? directory = Path.GetDirectoryName(outputPath);
        if (!string.IsNullOrEmpty(directory) && !Directory.Exists(directory))
        {
            Directory.CreateDirectory(directory);
        }

        WriteIcon(outputPath);
    }

    private static void WriteIcon(string outputPath)
    {
        byte[] iconBytes = Convert.FromBase64String(IconBase64);
        File.WriteAllBytes(outputPath, iconBytes);
    }
}
